// Stand-in for pi's SDK: exactly what extensions/antz-subagent.ts imports, with
// the least behaviour the tool needs to run. Adding an import or an SDK method
// to the extension means adding it here — that is the only thing this file has to
// keep up with, and a missing name fails the harness loudly rather than silently.
//
// The session factory is not here: the harness installs it on
// globalThis.__mkSession, because the fake agents' timing, output and failures
// are the input each check varies.
export const CONFIG_DIR_NAME = ".pi";
// Project agents win, so the fixture under the temp cwd is always what loads and
// the developer's real ~/.pi/agent is never read.
export const getAgentDir = () => "/nonexistent-agent-dir";
export const keyHint = () => "";
export const SessionManager = { inMemory: () => ({}) };
export const ModelRuntime = { create: async () => ({}) };

export class DefaultResourceLoader {
  async reload() {}
  // What the tool reads to name the skills a child is handed. The harness sets
  // `__skills`; with none set the list is empty, which is also the real answer in
  // a repo that has no skills of its own.
  getSkills() {
    return { skills: globalThis.__skills ?? [], diagnostics: [] };
  }
}

export const createAgentSession = (options) => globalThis.__mkSession(options);

// No fixture pins a model, so the tool never resolves one.
export const resolveCliModel = () => ({});

// The shape the tool needs: name, description, tools, and the body below the
// frontmatter. Not a YAML parser.
export function parseFrontmatter(raw) {
  const match = /^---\n([\s\S]*?)\n---\n?([\s\S]*)$/.exec(raw);
  if (!match) return { frontmatter: {}, body: raw };
  const frontmatter = {};
  for (const line of match[1].split("\n")) {
    const colon = line.indexOf(":");
    if (colon > 0) frontmatter[line.slice(0, colon).trim()] = line.slice(colon + 1).trim();
  }
  return { frontmatter, body: match[2] };
}
